sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // 1. Extract payload
    var body = request.body.data || {};

    var inputs = {};
    inputs['model'] = body.model || null; 
    inputs['prompt'] = body.prompt || null; 
    inputs['attachment_sys_id'] = body.attachment_sys_id || null; 

    try {
        // 2. Execute Subflow
        var result = sn_fd.FlowAPI.getRunner()
            .subflow('x_1815796_itsmgr_0.generic_send_receive')
            .inForeground()
            .withInputs(inputs)
            .run();

        var outputs = result.getOutputs();

        var file_contents = outputs['file_contents']; 
        var file_id = outputs['file_id']; 
        var bot_answer = outputs['bot_answer']; 

        // 3. Return Success Response
        response.setStatus(200);
        response.setBody({
            "status": "success",
            "bot_answer": bot_answer,
            "file_id": file_id,
            "file_contents": file_contents
        });

    } catch (ex) {
        // 4. Handle and Log Hard Failures
        var errorMessage = ex.message || ex.toString();
        gs.error("Error in Scripted REST API (Generic Subflow): " + errorMessage);

        response.setStatus(500);
        response.setBody({
            "status": "failure",
            "message": errorMessage
        });
    }
})(request, response);
